        result.set("result", fixture.path("raw").path("finalMessage").deepCopy());
        result.set("providerState", fixture.path("raw").path("providerState").deepCopy());
        return result;
    }

    private static ObjectNode projectAgentLoop(JsonNode fixture) {
        JsonNode events = requireArray(fixture.path("raw").path("events"), "agent-loop raw.events");
        JsonNode messages = requireArray(fixture.path("raw").path("messages"), "agent-loop raw.messages");
        boolean toolStarted = false;
