            if (event.has("toolResults")) projected.set("toolResultRoles", roles(event.path("toolResults")));
            projectedEvents.add(projected);
        }
        if (!toolStarted || !toolEnded) throw new IllegalArgumentException("agent-loop fixture must execute a tool");
        ObjectNode result = MAPPER.createObjectNode();
        result.set("events", projectedEvents);
        result.set("messages", messages.deepCopy());
        return result;
    }

    private static ObjectNode projectSession(JsonNode fixture) {
        JsonNode log = requireArray(fixture.path("raw").path("log"), "session raw.log");
        ArrayNode logKinds = MAPPER.createArrayNode();
        ArrayNode entryRoles = MAPPER.createArrayNode();
        for (int index = 0; index < log.size(); index++) {
            JsonNode item = log.get(index);
            if (item.path("seq").asInt() != index + 1) throw new IllegalArgumentException("session log sequence must be contiguous");
            String kind = item.path("kind").asText();
            logKinds.add(kind);
            if ("entry".equals(kind)) {
                if (item.path("entry").path("seq").asInt() != index + 1) throw new IllegalArgumentException("entry wrapper sequence mismatch");
                if ("message".equals(item.path("entry").path("type").asText())) {
                    entryRoles.add(item.path("entry").path("message").path("role").asText());
                }
            } else if ("record".equals(kind) && item.path("record").path("seq").asInt() != index + 1) {
                throw new IllegalArgumentException("record wrapper sequence mismatch");
            }
        }
        if (!entryRoles.equals(MAPPER.valueToTree(List.of("user", "assistant", "toolResult")))) {
            throw new IllegalArgumentException("session fixture must preserve Pi message roles");
        }
        ArrayNode openIds = MAPPER.createArrayNode();
        fixture.path("raw").path("openOperations").forEach(operation -> openIds.add(operation.path("id").asText()));
        ObjectNode result = MAPPER.createObjectNode();
        result.set("log", log.deepCopy());
        result.set("leafId", fixture.path("raw").path("leafId").deepCopy());
        result.set("openOperationIds", openIds);
        result.set("logKinds", logKinds);
        result.set("entryRoles", entryRoles);
        return result;
    }

    private static ObjectNode projectCompaction(JsonNode fixture) {
        JsonNode raw = fixture.path("raw");
        JsonNode preparation = raw.path("preparation");
        requireArray(preparation.path("retainedTail"), "compaction preparation.retainedTail");
        ObjectNode result = MAPPER.createObjectNode();
        copy(result, "settings", preparation.path("settings"));
        copy(result, "messagesToSummarize", preparation.path("messagesToSummarize"));
        copy(result, "turnPrefixMessages", preparation.path("turnPrefixMessages"));
        copy(result, "retainedTail", preparation.path("retainedTail"));
        result.put("isSplitTurn", preparation.path("isSplitTurn").asBoolean());
        copy(result, "tokensBefore", preparation.path("tokensBefore"));
        if (preparation.has("previousSummary")) copy(result, "previousSummary", preparation.path("previousSummary"));
        else result.putNull("previousSummary");
        copy(result, "fileOps", preparation.path("fileOps"));
        copy(result, "rebuiltContext", raw.path("context"));
        copy(result, "tokenEstimates", raw.path("tokenEstimates"));
        copy(result, "serializedConversation", raw.path("serializedConversation"));
        return result;
    }

    private static ObjectNode projectProtocol(JsonNode fixture) {
        JsonNode raw = fixture.path("raw");
        String frameHex = raw.path("frameHex").asText();
        String payloadHex = raw.path("payloadHex").asText();
        if (!frameHex.equals(fixture.path("assertion").path("frameHex").asText())
                || !payloadHex.equals(fixture.path("assertion").path("payloadHex").asText())) {
            throw new IllegalArgumentException("protocol wire bytes differ from the pinned Pi assertion");
        }
        byte[] frame = java.util.HexFormat.of().parseHex(frameHex);
        if (frame.length < 4) throw new IllegalArgumentException("protocol frame is truncated");
        int payloadLength = java.nio.ByteBuffer.wrap(frame, 0, 4).getInt();
        if (payloadLength != frame.length - 4 || !payloadHex.equals(java.util.HexFormat.of().formatHex(frame, 4, frame.length))) {
            throw new IllegalArgumentException("protocol frame length or payload mismatch");
        }
        if (raw.path("decoded").size() != 1) throw new IllegalArgumentException("protocol fragmented decode must yield one message");
        ObjectNode result = MAPPER.createObjectNode();
        for (String field : List.of("parsed", "decoded", "payloadHex", "frameHex", "frameBase64")) copy(result, field, raw.path(field));
        return result;
    }

    private static ObjectNode projectSessionBranchFork(JsonNode fixture) {
        JsonNode raw = fixture.path("raw");
        ArrayNode forkEntryIds = MAPPER.createArrayNode();
        raw.path("fork").path("entries").forEach(entry -> forkEntryIds.add(entry.path("id").asText()));
        if (!forkEntryIds.equals(fixture.path("assertion").path("forkEntries"))
                || raw.path("fork").path("records").size() != 0
                || !raw.path("fork").path("metadata").path("parentSessionId").asText()
                        .equals(fixture.path("assertion").path("forkParentSessionId").asText())) {
            throw new IllegalArgumentException("branch fork differs from the pinned Pi path and provenance behavior");
        }
        ObjectNode result = MAPPER.createObjectNode();
        copy(result, "source", raw.path("source"));
        copy(result, "fork", raw.path("fork"));
        return result;
    }

    private static ObjectNode projectAgentQueueAbort(JsonNode fixture) {
        JsonNode raw = fixture.path("raw");
        ObjectNode steer = summarizeLoop(raw.path("steer"));
        ObjectNode followUp = summarizeLoop(raw.path("followUp"));
        ObjectNode aborted = summarizeLoop(raw.path("aborted"));
        if (!steer.path("userMessages").toString().contains("interrupt")
                || steer.path("toolResultIds").size() != 2
                || !raw.path("executed").equals(MAPPER.valueToTree(List.of("first", "second")))) {
            throw new IllegalArgumentException("steer was not injected after the complete Pi Tool batch");
        }
        long turnStarts = java.util.stream.StreamSupport.stream(
                followUp.path("eventTypes").spliterator(), false)
                .filter(value -> "turn_start".equals(value.asText())).count();
        ArrayNode followUpUsers = (ArrayNode) followUp.path("userMessages");
        ArrayNode abortedStops = (ArrayNode) aborted.path("assistantStopReasons");
        if (followUpUsers.isEmpty() || !"follow up".equals(followUpUsers.get(followUpUsers.size() - 1).asText())
                || turnStarts != 2 || abortedStops.isEmpty()
                || !abortedStops.get(abortedStops.size() - 1).asText()
                        .equals(fixture.path("assertion").path("abortedStopReason").asText())) {
            throw new IllegalArgumentException("follow-up or abort differs from the pinned Pi behavior");
        }
        ObjectNode result = MAPPER.createObjectNode();
        result.set("steer", steer);
        result.set("followUp", followUp);
        result.set("aborted", aborted);
        copy(result, "executed", raw.path("executed"));
        return result;
    }

    private static ObjectNode summarizeLoop(JsonNode run) {
        ObjectNode summary = MAPPER.createObjectNode();
        ArrayNode eventTypes = MAPPER.createArrayNode();
        run.path("events").forEach(event -> eventTypes.add(event.path("type").asText()));
        ArrayNode messageRoles = MAPPER.createArrayNode();
        ArrayNode userMessages = MAPPER.createArrayNode();
        ArrayNode toolResultIds = MAPPER.createArrayNode();
        ArrayNode assistantStopReasons = MAPPER.createArrayNode();
        run.path("messages").forEach(message -> {
            String role = message.path("role").asText();
            messageRoles.add(role);
            if ("user".equals(role)) userMessages.add(message.path("content").asText());
            if ("toolResult".equals(role)) toolResultIds.add(message.path("toolCallId").asText());
            if ("assistant".equals(role)) assistantStopReasons.add(message.path("stopReason").asText());
        });
        summary.set("eventTypes", eventTypes);
        summary.set("messageRoles", messageRoles);
        summary.set("userMessages", userMessages);
        summary.set("toolResultIds", toolResultIds);
        summary.set("assistantStopReasons", assistantStopReasons);
        return summary;
    }

    private static ObjectNode projectWorkspaceTools(JsonNode fixture) {
        JsonNode raw = fixture.path("raw");
        JsonNode assertion = fixture.path("assertion");
        if (!raw.path("read").path("text").asText().contains(assertion.path("readLine").asText())
                || !raw.path("write").path("content").equals(assertion.path("writtenContent"))
                || !raw.path("edit").path("content").equals(assertion.path("editedContent"))
                || !raw.path("shell").path("text").equals(assertion.path("shellOutput"))) {
            throw new IllegalArgumentException("workspace Tool result differs from the pinned Pi behavior");
        }
        return raw.deepCopy();
    }

    private static ObjectNode projectResourcePromptUsage(JsonNode fixture) {
        JsonNode raw = fixture.path("raw");
        JsonNode assertion = fixture.path("assertion");
        ArrayNode skillNames = MAPPER.createArrayNode();
        raw.path("skills").forEach(skill -> skillNames.add(skill.path("name").asText()));
        if (!raw.path("promptInvocation").equals(assertion.path("promptInvocation"))
                || !skillNames.equals(assertion.path("visibleSkills"))
                || raw.path("usage").path("belowThreshold").asBoolean()
                || !raw.path("usage").path("aboveThreshold").asBoolean()
                || raw.path("usage").path("disabled").asBoolean()) {
            throw new IllegalArgumentException("resource, prompt, usage, or compaction threshold differs from Pi");
        }
        return raw.deepCopy();
    }

    private static void requireEnvelope(JsonNode fixture) {
        if (!"1.0".equals(fixture.path("schemaVersion").asText())
                || fixture.path("fixtureId").asText().isBlank()
                || fixture.path("domain").asText().isBlank()) {
            throw new IllegalArgumentException("invalid Pi fixture envelope");
        }
        JsonNode source = fixture.path("source");
        if (!"https://github.com/earendil-works/pi.git".equals(source.path("repository").asText())
                || !PI_REVISION.equals(source.path("revision").asText())
                || !"0.84.3".equals(source.path("packageVersion").asText())) {
            throw new IllegalArgumentException("fixture is not bound to the approved Pi source revision");
        }
    }

    private static JsonNode requireArray(JsonNode value, String name) {
        if (!value.isArray()) throw new IllegalArgumentException(name + " must be an array");
        return value;
    }

    private static ObjectNode pickDefined(JsonNode value, List<String> fields) {
        ObjectNode result = MAPPER.createObjectNode();
        for (String field : fields) if (value.has(field)) result.set(field, value.path(field).deepCopy());
        return result;
    }

    private static ArrayNode roles(JsonNode messages) {
        ArrayNode result = MAPPER.createArrayNode();
        messages.forEach(message -> result.add(message.path("role").asText()));
        return result;
    }

    private static void copy(ObjectNode target, String field, JsonNode value) {
        target.set(field, value.deepCopy());
    }

    private static JsonNode sortObject(JsonNode value) {
        if (value.isArray()) {
            ArrayNode result = MAPPER.createArrayNode();
            value.forEach(element -> result.add(sortObject(element)));
            return result;
        }
        if (value.isObject()) {
            ObjectNode result = MAPPER.createObjectNode();
            Map<String, JsonNode> sorted = new TreeMap<>();
            value.properties().forEach(entry -> sorted.put(entry.getKey(), entry.getValue()));
            sorted.forEach((key, child) -> result.set(key, sortObject(child)));
            return result;
        }
        return value.deepCopy();
    }
}
